contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Call getTokens with a provided Ether amount and check the invariant or unchanged state
    function run(uint256 sendAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (sendAmount)); require(sendAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= sendAmount);

        // read before-values
        uint256 beforeTotalSupply = c.totalSupply(); if (__ESBMC_reverted()) return;
        uint256 beforeTotalDistributed = c.totalDistributed(); if (__ESBMC_reverted()) return;
        uint256 beforeTotalRemaining = c.totalRemaining(); if (__ESBMC_reverted()) return;

        bool reverted;
        // perform the state-changing call as a top-level statement
        c.getTokens{value: sendAmount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // read after-values
        uint256 afterTotalSupply = c.totalSupply(); if (__ESBMC_reverted()) return;
        uint256 afterTotalDistributed = c.totalDistributed(); if (__ESBMC_reverted()) return;
        uint256 afterTotalRemaining = c.totalRemaining(); if (__ESBMC_reverted()) return;

        // Single general assertion: either reverted and all three public totals unchanged, or succeeded and invariant holds
        assert( (reverted && afterTotalSupply == beforeTotalSupply && afterTotalDistributed == beforeTotalDistributed && afterTotalRemaining == beforeTotalRemaining)
                || (!reverted && afterTotalSupply == (afterTotalDistributed + afterTotalRemaining)) );
    }

    receive() external payable {}
}

