// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {NewIntelTechMedia} from "../src/NewIntelTechMedia.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    NewIntelTechMedia c;

    function setUp() public {
        c = new NewIntelTechMedia();
    }

    function _run(uint256 sendAmount) internal {
        sendAmount = bound(sendAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= sendAmount);
        uint256 beforeTotalSupply;
        try c.totalSupply() returns (uint256 __r) { beforeTotalSupply = __r; } catch { return; }
        uint256 beforeTotalDistributed;
        try c.totalDistributed() returns (uint256 __r) { beforeTotalDistributed = __r; } catch { return; }
        uint256 beforeTotalRemaining;
        try c.totalRemaining() returns (uint256 __r) { beforeTotalRemaining = __r; } catch { return; }
        bool reverted;
        try c.getTokens{value: sendAmount}() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 afterTotalSupply;
        try c.totalSupply() returns (uint256 __r) { afterTotalSupply = __r; } catch { return; }
        uint256 afterTotalDistributed;
        try c.totalDistributed() returns (uint256 __r) { afterTotalDistributed = __r; } catch { return; }
        uint256 afterTotalRemaining;
        try c.totalRemaining() returns (uint256 __r) { afterTotalRemaining = __r; } catch { return; }
        assertTrue((reverted && afterTotalSupply == beforeTotalSupply && afterTotalDistributed == beforeTotalDistributed && afterTotalRemaining == beforeTotalRemaining)
                || (!reverted && afterTotalSupply == (afterTotalDistributed + afterTotalRemaining)));
    }

    function testFuzz_run(uint256 sendAmount) public {
        _run(sendAmount);
    }

    receive() external payable {}
}
